/**
 * db.js - Capa de datos para Eco-Trueque Escolar (Colegio N° 10)
 * Soporta conexión directa a Supabase y modo local automático (localStorage)
 * para uso inmediato en el aula.
 *
 * ============================================================================
 * SQL PARA EJECUTAR EN SUPABASE (SQL Editor):
 * ============================================================================
 * create table items_donados (
 *   id bigint generated by default as identity primary key,
 *   categoria text not null, -- 'uniforme' | 'utiles' | 'alimentos'
 *   nombre text not null,
 *   talle_detalle text,
 *   stock int not null default 1,
 *   entregados int not null default 0,
 *   peso_unit_kg numeric(5,2) default 0.25,
 *   created_at timestamptz default now()
 * );
 *
 * create table solicitudes_anonimas (
 *   id bigint generated by default as identity primary key,
 *   item_id bigint references items_donados(id),
 *   item_nombre text not null,
 *   tipo text default 'catalogo', -- 'catalogo' | 'colecta_libre'
 *   usuario_interno text not null, -- Solo gestión interna (no visible en UI pública)
 *   curso text not null,           -- Solo gestión interna
 *   estado text default 'pendiente',
 *   created_at timestamptz default now()
 * );
 *
 * create table delegados_curso (
 *   id bigint generated by default as identity primary key,
 *   curso text not null,
 *   generacion_legado text not null, -- '5° Año (Mentores)' | '4° Año (Herederos)'
 *   campania_alimento text not null,
 *   meta_unidades int not null default 50,
 *   actual_unidades int not null default 0
 * );
 * ============================================================================
 */

// 1. REEMPLAZAR CON LAS CLAVES REALES DEL PROYECTO SUPABASE DEL COLEGIO N° 10
export const SUPABASE_URL = 'https://TU-PROYECTO-COLEGIO10.supabase.co';
export const SUPABASE_ANON_KEY = 'TU_SUPABASE_ANON_KEY_AQUI';

const STORAGE_KEYS = {
  ITEMS: 'ecotrueque_items_v1',
  SOLICITUDES: 'ecotrueque_solicitudes_v1',
  DELEGADOS: 'ecotrueque_delegados_v1'
};

// Detecta si el docente/alumnos ya configuraron las credenciales reales
export function isSupabaseConfigured() {
  return (
    SUPABASE_URL.startsWith('https://') &&
    !SUPABASE_URL.includes('TU-PROYECTO') &&
    SUPABASE_ANON_KEY !== 'TU_SUPABASE_ANON_KEY_AQUI' &&
    SUPABASE_ANON_KEY.length > 20
  );
}

