function initLocalSeed() {
  if (!localStorage.getItem(STORAGE_KEYS.ITEMS)) {
    localStorage.setItem(STORAGE_KEYS.ITEMS, JSON.stringify(SEED_ITEMS));
  }
  if (!localStorage.getItem(STORAGE_KEYS.SOLICITUDES)) {
    localStorage.setItem(STORAGE_KEYS.SOLICITUDES, JSON.stringify(SEED_SOLICITUDES));
  }
  if (!localStorage.getItem(STORAGE_KEYS.DELEGADOS)) {
    localStorage.setItem(STORAGE_KEYS.DELEGADOS, JSON.stringify(SEED_DELEGADOS));
  }
}

async function supabaseFetch(table, options = {}) {
  const url = `${SUPABASE_URL}/rest/v1/${table}${options.query || ''}`;
  const headers = {
    apikey: SUPABASE_ANON_KEY,
    Authorization: `Bearer ${SUPABASE_ANON_KEY}`,
    'Content-Type': 'application/json',
    Prefer: 'return=representation'
  };
  const res = await fetch(url, {
    method: options.method || 'GET',
    headers,
    body: options.body ? JSON.stringify(options.body) : undefined
  });
  if (!res.ok) throw new Error(`Error Supabase (${res.status})`);
  return res.json();
}

export async function obtenerItemsDonados() {
  initLocalSeed();
  if (isSupabaseConfigured()) {
    try {
      return await supabaseFetch('items_donados', { query: '?select=*&order=id.asc' });
    } catch (e) {
      console.warn('Usando respaldo local para items_donados:', e.message);
    }
  }
  return JSON.parse(localStorage.getItem(STORAGE_KEYS.ITEMS));
}

export async function agregarItemDonado(nuevoItem) {
  initLocalSeed();
  const payload = {
    categoria: nuevoItem.categoria,
    nombre: nuevoItem.nombre.trim(),
    talle_detalle: nuevoItem.talle_detalle.trim(),
    stock: Number(nuevoItem.stock) || 1,
    entregados: 0,
    peso_unit_kg: nuevoItem.categoria === 'uniforme' ? 0.35 : 0.15
  };

  if (isSupabaseConfigured()) {
    try {
      const [created] = await supabaseFetch('items_donados', {
        method: 'POST',
        body: payload
      });
      return created;
    } catch (e) {
      console.warn('Guardando donación en modo local:', e.message);
    }
  }

  const items = JSON.parse(localStorage.getItem(STORAGE_KEYS.ITEMS));
  const itemConId = { ...payload, id: Date.now() };
  items.unshift(itemConId);
  localStorage.setItem(STORAGE_KEYS.ITEMS, JSON.stringify(items));
  return itemConId;
}

/**
 * Registra una solicitud 100% anónima hacia el público.
 * En la base sólo se guarda usuario_interno y curso para gestión interna de retiro.
 */
export async function crearSolicitudAnonima({ item_id, item_nombre, tipo, usuario_interno, curso }) {
  initLocalSeed();
  const registro = {
    item_id: item_id ? Number(item_id) : null,
    item_nombre: item_nombre.trim(),
    tipo: tipo || 'catalogo',
    usuario_interno: usuario_interno.trim(),
    curso: curso.trim(),
    estado: 'pendiente',
    created_at: new Date().toISOString()
  };

  if (isSupabaseConfigured()) {
    try {
      await supabaseFetch('solicitudes_anonimas', {
        method: 'POST',
        body: registro
      });
    } catch (e) {
      console.warn('Guardando solicitud anónima en almacenamiento local:', e.message);
    }
  }

  // Actualizar stock e historial local
  const solicitudes = JSON.parse(localStorage.getItem(STORAGE_KEYS.SOLICITUDES));
  solicitudes.push({ ...registro, id: Date.now() });
  localStorage.setItem(STORAGE_KEYS.SOLICITUDES, JSON.stringify(solicitudes));

  if (item_id) {
    const items = JSON.parse(localStorage.getItem(STORAGE_KEYS.ITEMS));
    const idx = items.findIndex((i) => Number(i.id) === Number(item_id));
    if (idx !== -1 && items[idx].stock > 0) {
      items[idx].stock -= 1;
      items[idx].entregados = (items[idx].entregados || 0) + 1;
      localStorage.setItem(STORAGE_KEYS.ITEMS, JSON.stringify(items));
    }
  }

  return { ok: true };
}

export async function obtenerColectasDelegados() {
  initLocalSeed();
  if (isSupabaseConfigured()) {
    try {
      return await supabaseFetch('delegados_curso', { query: '?select=*&order=id.asc' });
    } catch (e) {
      console.warn('Usando respaldo local para delegados_curso:', e.message);
    }
  }
  return JSON.parse(localStorage.getItem(STORAGE_KEYS.DELEGADOS));
}

export async function sumarAporteAlimento(idCampania, cantidadSumar) {
  initLocalSeed();
  const cant = Math.max(1, Number(cantidadSumar) || 1);
  const colectas = JSON.parse(localStorage.getItem(STORAGE_KEYS.DELEGADOS));
  const idx = colectas.findIndex((c) => Number(c.id) === Number(idCampania));
  if (idx !== -1) {
    colectas[idx].actual_unidades += cant;
    localStorage.setItem(STORAGE_KEYS.DELEGADOS, JSON.stringify(colectas));
  }
  return colectas;
}

export async function crearCampaniaAlimento({ campania_alimento, meta_unidades, curso }) {
  initLocalSeed();
  const colectas = JSON.parse(localStorage.getItem(STORAGE_KEYS.DELEGADOS));
  colectas.push({
    id: Date.now(),
    curso: curso || 'Comunidad Colegio N° 10',
    generacion_legado: 'Necesidad Puntual',
    campania_alimento: campania_alimento.trim(),
    meta_unidades: Math.max(5, Number(meta_unidades) || 20),
    actual_unidades: 0
  });
  localStorage.setItem(STORAGE_KEYS.DELEGADOS, JSON.stringify(colectas));
  return colectas;
}

/**
 * Devuelve únicamente totales agregados para el Panel Matemático
 * sin exponer NUNCA los nombres/códigos de usuario_interno.
 */
export async function obtenerResumenMatematico() {
  initLocalSeed();
  const items = await obtenerItemsDonados();
  const colectas = await obtenerColectasDelegados();
  const solicitudes = JSON.parse(localStorage.getItem(STORAGE_KEYS.SOLICITUDES));

  let prendasReutilizadas = 0;
  let utilesReutilizados = 0;
  let stockUniformes = 0;
  let stockUtiles = 0;
  let kgTextiles = 0;

  items.forEach((it) => {
    const entregados = Number(it.entregados) || 0;
    const stock = Number(it.stock) || 0;
    if (it.categoria === 'uniforme') {
      prendasReutilizadas += entregados;
      stockUniformes += stock;
      kgTextiles += entregados * (Number(it.peso_unit_kg) || 0.35);
    } else if (it.categoria === 'utiles') {
      utilesReutilizados += entregados;
      stockUtiles += stock;
    }
  });

  const totalMetaAlimentos = colectas.reduce((acc, c) => acc + Number(c.meta_unidades), 0);
  const totalActualAlimentos = colectas.reduce((acc, c) => acc + Number(c.actual_unidades), 0);

  // Estudiantes asistidos = base histórica de entregas + solicitudes registradas
  const estudiantesAsistidos = prendasReutilizadas + utilesReutilizados + solicitudes.length;

  return {
    prendasReutilizadas,
    utilesReutilizados,
    totalArticulosReutilizados: prendasReutilizadas + utilesReutilizados,
    stockUniformes,
    stockUtiles,
    kgTextiles: Number(kgTextiles.toFixed(2)),
    estudiantesAsistidos,
    totalMetaAlimentos,
    totalActualAlimentos,
    colectas
  };
}

